import os, shutil
from pathlib import Path

def run():
    dl = Path.home() / 'Downloads'
    buckets = {'PDFs': ['.pdf', '.epub'], 'Archives': ['.zip', '.tar', '.7z'], 'Installers': ['.exe', '.msi'], 'Images': ['.png', '.jpg', '.webp']}
    moved = 0
    for f in dl.iterdir():
        if f.is_file():
            for folder, exts in buckets.items():
                if f.suffix.lower() in exts:
                    target = dl / folder
                    target.mkdir(exist_ok=True)
                    shutil.move(str(f), str(target / f.name))
                    moved += 1
    return f'Sorted {moved} files into clean subfolders.'

if __name__ == '__main__':
    print(run())

import psutil

def run():
    whitelist = {'python.exe', 'ollama.exe', 'code.exe', 'explorer.exe'}
    report = []
    for proc in psutil.process_iter(['pid', 'name', 'memory_info']):
        try:
            mem_mb = proc.info['memory_info'].rss / (1024 * 1024)
            if mem_mb > 1200 and proc.info['name'].lower() not in whitelist:
                report.append(f"{proc.info['name']} ({int(mem_mb)} MB)")
        except Exception:
            pass
    return 'Identified heavy processes: ' + (', '.join(report) if report else 'None above 1.2GB')

if __name__ == '__main__':
    print(run())

import webbrowser

def run():
    urls = [
        'https://arxiv.org/search/?query=low+latency+speech+synthesis&searchtype=all',
        'https://arxiv.org/search/?query=faster+whisper+streaming+vad&searchtype=all'
    ]
    for u in urls:
        webbrowser.open_new_tab(u)
    return 'Opened ArXiv research queries in default browser.'

if __name__ == '__main__':
    print(run())

import subprocess

def run():
    res = subprocess.run(['nvidia-smi', '--query-gpu=temperature.gpu,memory.used,memory.total', '--format=csv,noheader'], capture_output=True, text=True)
    return res.stdout.strip() if res.returncode == 0 else 'NVIDIA GPU telemetry unavailable'

if __name__ == '__main__':
    print(run())
